using System.Collections.Generic;using System.Linq;using System.Threading.Tasks;using System.Windows.Controls;
namespace BF4Launcher;
public partial class MainWindow {
 public Task<Dictionary<string,bool>> CheckV2ViewsAsync(){var checks=new Dictionary<string,bool>();checks["v2-runtime-check-button"]=ServiceButtons.Children.OfType<Button>().Any(b=>b.Content?.ToString()=="检查运行文件");checks["v2-battlelog-address-entry"]=ServiceButtons.Children.OfType<Button>().Any(b=>b.Content?.ToString()=="复制 Battlelog 地址");checks["v2-conquest-catalog-12"]=repo.Maps.Count(m=>m.Modes.Contains("ConquestLarge0"))==12;checks["v2-air-mode-available"]=repo.Modes.Any(m=>m.Id=="AirSuperiority0");checks["v2-new-hook-editors"]=new[]{"botRandomRank","externalIp","externalPort"}.All(id=>repo.Fields.Any(f=>f.Id==id));AddModeCombo.SelectedValue="AirSuperiority0";checks["v2-map-mode-ui-air"]=AddMapCombo.Items.Count==33;AddMapCombo.SelectedValue="MP_Damage";AddModeCombo.SelectedValue="ConquestLarge0";checks["v2-map-mode-ui-conquest"]=AddMapCombo.Items.Count==12&&AddMapCombo.SelectedValue is string map&&repo.Maps.Any(m=>m.Id==map&&m.Modes.Contains("ConquestLarge0"));var row=new RotationEntry{AllMaps=repo.Maps,Mode="AirSuperiority0",Map="MP_Damage"};row.Mode="ConquestLarge0";checks["v2-row-mode-change-keeps-valid-selection"]=row.AvailableMaps.Any(m=>m.Id==row.Map);((Button)FindName("NavLaunch")).RaiseEvent(new System.Windows.RoutedEventArgs(Button.ClickEvent));CapturePreview("v2-launch-page");((Button)FindName("NavServer")).RaiseEvent(new System.Windows.RoutedEventArgs(Button.ClickEvent));foreach(var card in ServerFields.Children.OfType<System.Windows.Controls.Border>()){if(card.Child is System.Windows.Controls.StackPanel panel&&panel.Children.OfType<System.Windows.Controls.TextBlock>().FirstOrDefault()?.Text is string group&&group is "高级连接" or "Bot 基础开关")CaptureElement(card,group=="高级连接"?"v2-advanced-settings":"v2-bot-settings",900,group=="高级连接"?280:480);}return Task.FromResult(checks);}
}
